export namespace Effect {
  export interface Effect<A, E = never, R = never> {
    readonly _A: A
    readonly _E: E
    readonly _R: R
    [Symbol.iterator](): Generator<Effect<unknown>, A, unknown>
  }
}
export const Effect: {
  readonly never: Effect.Effect<never>
  forkChild<A, E, R>(effect: Effect.Effect<A, E, R>): Effect.Effect<{ readonly child: true }, never, R>
  forkScoped<A, E, R>(effect: Effect.Effect<A, E, R>): Effect.Effect<{ readonly scoped: true }, never, R>
  forkDetach<A, E, R>(effect: Effect.Effect<A, E, R>): Effect.Effect<{ readonly detached: true }, never, R>
  gen<A>(f: () => Generator<Effect.Effect<unknown>, A, unknown>): Effect.Effect<A>
}
export const Layer: {
  effectDiscard<A, E, R>(effect: Effect.Effect<A, E, R>): unknown
}
export const Fiber: {
  interrupt(fiber: { readonly detached: true }): Effect.Effect<void>
}
export const FiberHandle: {
  make(): Effect.Effect<{ readonly handle: true }>
  run(handle: { readonly handle: true }, effect: Effect.Effect<unknown>): Effect.Effect<unknown>
  set(handle: { readonly handle: true }, fiber: { readonly detached: true }): Effect.Effect<void>
}
